\section*{Claim}
The stochastic total-rate inequality yields a force-budget inversion theorem and a precise version of the paper's regime demarcation. Define
\begin{align*}
T_A&:=\overline{\left|\int_0^\tau(d\langle A\rangle-\langle dA\rangle)\right|},\\
S_A&:=\int_0^\tau\sigma_{A,\mu}\sigma_f\,dt,\\
M_A&:=\int_0^\tau\langle f\rangle|\langle A\rangle_\mu-\langle A\rangle|\,dt,\\
D_A&:=\left(\|\gamma\|_\infty^2\int_0^\tau\overline{\sigma_A^2}\,dt\right)^{1/2}.
\end{align*}
Then every stochastic replicator-mutator trajectory satisfying the paper's assumptions obeys
\[
T_A\leq S_A+M_A+D_A.
\]
Consequently, any observed or certified value of \(T_A\) imposes the necessary lower bounds
\begin{align*}
S_A&\geq \max\{T_A-M_A-D_A,0\},\\
M_A&\geq \max\{T_A-S_A-D_A,0\},\\
D_A&\geq \max\{T_A-S_A-M_A,0\}.
\end{align*}
If \(V_A:=\int_0^\tau\overline{\sigma_A^2}\,dt>0\), the last inequality is equivalently
\[
\|\gamma\|_\infty\geq \frac{\max\{T_A-S_A-M_A,0\}}{\sqrt{V_A}}.
\]
Thus the paper's three sources are not merely additive upper-bound terms: they form an exclusion certificate. A claimed trait-change magnitude exceeding the sum of any two terms forces the remaining source to be at least the residual gap. Normalised budget shares
\[
\theta_{\mathrm{sel}}:=\frac{S_A}{S_A+M_A+D_A},\quad
\theta_{\mathrm{mut}}:=\frac{M_A}{S_A+M_A+D_A},\quad
\theta_{\mathrm{drift}}:=\frac{D_A}{S_A+M_A+D_A}
\]
therefore provide a quantitative version of the paper's selection-, mutation-, and drift-dominated regimes whenever \(S_A+M_A+D_A>0\).

\section*{Premises}
\begin{align*}
(P1)\quad &T_A,S_A,M_A,D_A\geq0.\\
(P2)\quad &T_A\leq S_A+M_A+D_A.\\
(P3)\quad &D_A=\|\gamma\|_\infty\sqrt{V_A},\quad V_A:=\int_0^\tau\overline{\sigma_A^2}\,dt.\\
(P4)\quad &\text{For nonnegative }x,y,z,\quad x\leq y+z\Longrightarrow x-z\leq y.\\
(P5)\quad &\text{For nonnegative }y,\quad y\geq q\Longleftrightarrow y\geq\max\{q,0\}\text{ whenever }q\leq y.\\
(P6)\quad &\text{For a sequence indexed by }m,\quad S_A\gg\{M_A,D_A\}\text{ means }M_A/S_A\to0\text{ and }D_A/S_A\to0.
\end{align*}

\section*{Derivation}
Starting from the stochastic total bound,
\begin{align*}
T_A&\leq S_A+M_A+D_A &&\text{by }(P2).
\end{align*}
Subtracting the two non-selected budgets gives
\begin{align*}
T_A-M_A-D_A&\leq S_A,\\
T_A-S_A-D_A&\leq M_A,\\
T_A-S_A-M_A&\leq D_A. &&\text{by algebra and }(P4)
\end{align*}
Since each budget is nonnegative by \((P1)\), these imply
\begin{align*}
S_A&\geq\max\{T_A-M_A-D_A,0\},\\
M_A&\geq\max\{T_A-S_A-D_A,0\},\\
D_A&\geq\max\{T_A-S_A-M_A,0\}. &&\text{by }(P5)
\end{align*}
If \(V_A>0\), then using \((P3)\),
\begin{align*}
\|\gamma\|_\infty\sqrt{V_A}
&=D_A\\
&\geq\max\{T_A-S_A-M_A,0\},
\end{align*}
so division by \(\sqrt{V_A}\) yields
\begin{align*}
\|\gamma\|_\infty
&\geq \frac{\max\{T_A-S_A-M_A,0\}}{\sqrt{V_A}}.
\end{align*}
Finally assume \(S_A+M_A+D_A>0\). The definitions of the shares give
\begin{align*}
\theta_{\mathrm{sel}}+\theta_{\mathrm{mut}}+\theta_{\mathrm{drift}}&=1,\\
\theta_{\mathrm{sel}}&=\frac{1}{1+M_A/S_A+D_A/S_A}\quad\text{when }S_A>0.
\end{align*}
Hence, along any sequence with \(S_A\gg\{M_A,D_A\}\),
\begin{align*}
\theta_{\mathrm{sel}}&\to1,
\end{align*}
while the same argument with the labels permuted gives \(\theta_{\mathrm{mut}}\to1\) for mutation-dominated sequences and \(\theta_{\mathrm{drift}}\to1\) for drift-dominated sequences.

\section*{Final Result}
\[
\boxed{\displaystyle
T_A\leq S_A+M_A+D_A,
\quad
S_A\geq\max\{T_A-M_A-D_A,0\},
\quad
M_A\geq\max\{T_A-S_A-D_A,0\},
\quad
D_A\geq\max\{T_A-S_A-M_A,0\}}
\]
\[
\boxed{\displaystyle
V_A>0\Longrightarrow
\|\gamma\|_\infty\geq\frac{\max\{T_A-S_A-M_A,0\}}{\sqrt{V_A}}}
\]
\hfill$\blacksquare$
